pub(crate) fn rec(p: &[i32], ki: i32, id: i32) -> i32 {
    // The word offset of record id of the variable section whose index is ki.
    return pw(p, sec(p, ki) + id);
}
pub(crate) fn leaf_at(p: &[i32], l: i32) -> i32 {
    return sec(p, 1) + (8 * l);
}
pub(crate) fn leaf_kind(p: &[i32], l: i32) -> i32 {
    return pw(p, leaf_at(p, l)) & 255;
}
pub(crate) fn combinator(p: &[i32], l: i32) -> bool {
    let k: i32 = leaf_kind(p, l);
    return (k == 16) || (k == 17);
}
pub(crate) fn check_typesets(p: &[i32], s: &mut [i32]) -> bool {
    let nt: i32 = pw(p, W_N_TYPESETS);
    let nl: i32 = pw(p, W_N_LEAVES);
    for t in 0..nt {
        let o: i32 = rec(p, 2, t);
        let na: i32 = pw(p, o);
        let ne: i32 = pw(p, o + 1);
        if !spend(s, 1 + (na + ne)) {
            return false;
        }
        // answers valid and strictly ascending
        for i in 0..na {
            let a: i32 = pw(p, o + (2 + i));
            if !in_range(a, nl) {
                bad(s, o + (2 + i), C_TYPESET);
                return false;
            }
            if (i > 0) && (a <= pw(p, o + (1 + i))) {
                bad(s, o + (2 + i), C_TYPESET);
                return false;
            }
            if (ne == 0) && combinator(p, a) {
                bad(s, o + (2 + i), C_TYPESET);
                return false;
            }
            // D141: an EXT leaf only ever answers through a combinator
            if leaf_kind(p, a) == 18 {
                bad(s, o + (2 + i), C_TYPESET);
                return false;
            }
        }
        if ne > 0 {
            // each answer once as itself, nothing twice, operands earlier
            let e: i32 = epoch(s);
            let eo: i32 = o + (2 + na);
            for j in 0..na {
                aux_set(s, pw(p, o + (2 + j)), e);
            }
            let mut seen_ans: i32 = 0;
            for k in 0..ne {
                let x: i32 = pw(p, eo + k);
                let mut l: i32 = x;
                let is_dep: bool = x < 0;
                if is_dep {
                    l = !x;
                }
                if !in_range(l, nl) {
                    bad(s, eo + k, C_TYPESET);
                    return false;
                }
                if mark_get(s, l) == e {
                    bad(s, eo + k, C_TYPESET);
                    return false;
                }
                if is_dep && (aux_get(s, l) == e) {
                    bad(s, eo + k, C_TYPESET);
                    return false;
                }
                if (!is_dep) && (aux_get(s, l) != e) {
                    bad(s, eo + k, C_TYPESET);
                    return false;
                }
                if !is_dep {
                    seen_ans += 1;
                }
                if combinator(p, l) {
                    let la: i32 = leaf_at(p, l);
                    let a1: i32 = pw(p, la + 2);
                    let a2: i32 = pw(p, la + 3);
                    if (!in_range(a1, nl)) || (!in_range(a2, nl)) {
                        bad(s, la, C_TYPESET);
                        return false;
                    }
                    if (mark_get(s, a1) != e) || (mark_get(s, a2) != e) {
                        bad(s, eo + k, C_TYPESET);
                        return false;
                    }
                }
                mark_set(s, l, e);
            }
            if seen_ans != na {
                bad(s, eo, C_TYPESET);
                return false;
            }
        }
    }
    // TS_ANY is {ANY}
    let ta: i32 = pw(p, W_TS_ANY);
    if ta >= 0 {
        let o2: i32 = rec(p, 2, ta);
        if (pw(p, o2) != 1) || (pw(p, o2 + 1) != 0) {
            bad(s, o2, C_TYPESET);
            return false;
        }
        let al: i32 = pw(p, o2 + 2);
        if (!in_range(al, nl)) || (leaf_kind(p, al) != 1) {
            bad(s, o2, C_TYPESET);
            return false;
        }
    }
    return !failed(s);
}
pub(crate) fn ts_eval_n(p: &[i32], t: i32) -> i32 {
    // Length of typeset t's evaluation list (the answers when n_eval = 0).
    let o: i32 = rec(p, 2, t);
    let ne: i32 = pw(p, o + 1);
    if ne > 0 {
        return ne;
    }
    return pw(p, o);
}
pub(crate) fn ts_eval_at(p: &[i32], t: i32, i: i32) -> i32 {
    // Leaf i of typeset t's evaluation list (dependencies as their leaf id).
    let o: i32 = rec(p, 2, t);
    let na: i32 = pw(p, o);
    let ne: i32 = pw(p, o + 1);
    if ne > 0 {
        let x: i32 = pw(p, o + (2 + (na + i)));
        if x < 0 {
            return !x;
        }
        return x;
    }
    return pw(p, o + (2 + i));
}
pub(crate) fn bound_ok(p: &[i32], b: &[u8], o: i32) -> bool {
    // A bound (region, a, b) at word o: region 0..5; infinities are 0, 0; a
    // big magnitude is a pool range of length >= 9 without a leading zero.
    let r: i32 = pw(p, o);
    let a: i32 = pw(p, o + 1);
    let c: i32 = pw(p, o + 2);
    if (r < 0) || (r > 5) {
        return false;
    }
    if (r == 0) || (r == 5) {
        return (a == 0) && (c == 0);
    }
    if (r == 1) || (r == 4) {
        return (byte_range(b, a, c) && (c >= 9)) && ((c <= 4096) && ((b[(a) as usize] as i32) != 0));
    }
    return true;
}
pub(crate) fn u64_cmp(ahi: i32, alo: i32, bhi: i32, blo: i32) -> i32 {
    if ahi != bhi {
        if i32::cast_unsigned(ahi) < i32::cast_unsigned(bhi) {
            return -1;
        }
        return 1;
    }
    if alo != blo {
        if i32::cast_unsigned(alo) < i32::cast_unsigned(blo) {
            return -1;
        }
        return 1;
    }
    return 0;
}
pub(crate) fn mag_cmp(b: &[u8], o1: i32, l1: i32, o2: i32, l2: i32) -> i32 {
    if l1 != l2 {
        return l1 - l2;
    }
    return bytes_cmp(b, o1, l1, o2, l2);
}
pub(crate) fn bcmp(p: &[i32], b: &[u8], x: i32, y: i32) -> i32 {
    // Compare the (valid) bounds at words x and y.
    let rx: i32 = pw(p, x);
    let ry: i32 = pw(p, y);
    if rx != ry {
        if rx < ry {
            return -1;
        }
        return 1;
    }
    if rx == 3 {
        return u64_cmp(pw(p, x + 1), pw(p, x + 2), pw(p, y + 1), pw(p, y + 2));
    }
    if rx == 2 {
        return u64_cmp(pw(p, y + 1), pw(p, y + 2), pw(p, x + 1), pw(p, x + 2));
    }
    if rx == 4 {
        return mag_cmp(b, pw(p, x + 1), pw(p, x + 2), pw(p, y + 1), pw(p, y + 2));
    }
    if rx == 1 {
        return mag_cmp(b, pw(p, y + 1), pw(p, y + 2), pw(p, x + 1), pw(p, x + 2));
    }
    return 0;
}
pub(crate) fn mag_succ(b: &[u8], vo: i32, vl: i32, wo: i32, wl: i32) -> bool {
    // Is magnitude w = magnitude v + 1?
    if wl == (vl + 1) {
        if (b[(wo) as usize] as i32) != 1 {
            return false;
        }
        for k in 0..vl {
            if ((b[(vo + k) as usize] as i32) != 255) || ((b[(wo + (k + 1)) as usize] as i32) != 0) {
                return false;
            }
        }
        return true;
    }
    if wl != vl {
        return false;
    }
    let mut i: i32 = vl - 1;
    while (i >= 0) && (((b[(vo + i) as usize] as i32) == 255) && ((b[(wo + i) as usize] as i32) == 0)) {
        i -= 1;
    }
    if i < 0 {
        return false;
    }
    if ((b[(vo + i) as usize] as i32) + 1) != (b[(wo + i) as usize] as i32) {
        return false;
    }
    for j in 0..i {
        if (b[(vo + j) as usize] as i32) != (b[(wo + j) as usize] as i32) {
            return false;
        }
    }
    return true;
}
pub(crate) fn is_succ(p: &[i32], b: &[u8], x: i32, y: i32) -> bool {
    // Is the bound at y exactly one more than the (finite) bound at x?
    let rx: i32 = pw(p, x);
    let ax: i32 = pw(p, x + 1);
    let cx: i32 = pw(p, x + 2);
    let ry: i32 = pw(p, y);
    let ay: i32 = pw(p, y + 1);
    let cy: i32 = pw(p, y + 2);
    if (rx == 3) && (ry == 3) {
        let lo: i32 = i32::wrapping_add(cx, 1);
        let mut hi: i32 = ax;
        if cx == (-1) {
            hi = i32::wrapping_add(ax, 1);
        }
        if cx == (-1) {
            if ax == (-1) {
                return false;
            }
        }
        return (ay == hi) && (cy == (lo | 0));
    }
    if (rx == 3) && (ry == 4) {
        return ((ax == (-1)) && (cx == (-1))) && ((cy == 9) && (((b[(ay) as usize] as i32) == 1) && ((((b[(ay + 1) as usize] as i32) | (b[(ay + 2) as usize] as i32)) == 0) && ((((b[(ay + 3) as usize] as i32) | (b[(ay + 4) as usize] as i32)) == 0) && ((((b[(ay + 5) as usize] as i32) | (b[(ay + 6) as usize] as i32)) == 0) && (((b[(ay + 7) as usize] as i32) | (b[(ay + 8) as usize] as i32)) == 0))))));
    }
    if (rx == 2) && (ry == 3) {
        return ((ax == 0) && (cx == 0)) && ((ay == 0) && (cy == 0));
    }
    if (rx == 2) && (ry == 2) {
        // value + 1 means n - 1
        if (ax == 0) && (cx == 0) {
            return false;
        }
        let lo2: i32 = i32::wrapping_sub(cx, 1);
        let mut hi2: i32 = ax;
        if cx == 0 {
            hi2 = i32::wrapping_sub(ax, 1);
        }
        return (ay == hi2) && (cy == lo2);
    }
    if (rx == 1) && (ry == 2) {
        return ((ay == (-1)) && (cy == (-1))) && ((cx == 9) && (((b[(ax) as usize] as i32) == 1) && ((((b[(ax + 1) as usize] as i32) | (b[(ax + 2) as usize] as i32)) == 0) && ((((b[(ax + 3) as usize] as i32) | (b[(ax + 4) as usize] as i32)) == 0) && ((((b[(ax + 5) as usize] as i32) | (b[(ax + 6) as usize] as i32)) == 0) && (((b[(ax + 7) as usize] as i32) | (b[(ax + 8) as usize] as i32)) == 0))))));
    }
    if (rx == 1) && (ry == 1) {
        return mag_succ(b, ay, cy, ax, cx);
    }
    if (rx == 4) && (ry == 4) {
        return mag_succ(b, ax, cx, ay, cy);
    }
    return false;
}
pub(crate) fn check_iv_records(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    let base: i32 = sec(p, 13);
    let n: i32 = pw(p, W_N_INTERVALS);
    for i in 0..n {
        let o: i32 = base + (6 * i);
        if !spend(s, 4) {
            return false;
        }
        if (!bound_ok(p, b, o)) || (!bound_ok(p, b, o + 3)) {
            bad(s, o, C_INTERVAL);
            return false;
        }
        if bcmp(p, b, o, o + 3) > 0 {
            bad(s, o, C_INTERVAL);
            return false;
        }
    }
    let fb: i32 = sec(p, 14);
    let nf: i32 = pw(p, W_N_FINTERVALS);
    for j in 0..nf {
        let fo: i32 = fb + (4 * j);
        if u64_cmp(pw(p, fo), pw(p, fo + 1), pw(p, fo + 2), pw(p, fo + 3)) > 0 {
            bad(s, fo, C_FINTERVAL);
            return false;
        }
    }
    return !failed(s);
}
pub(crate) fn iv_run_ok(p: &[i32], b: &[u8], s: &mut [i32], first: i32, n: i32) -> bool {
    // A leaf's interval run: in range, ascending, disjoint, non-adjacent.
    if (first < 0) || ((n < 0) || (n > (pw(p, W_N_INTERVALS) - first))) {
        return false;
    }
    let base: i32 = sec(p, 13);
    for i in 1..n {
        let pv: i32 = base + (6 * (first + (i - 1)));
        let cu: i32 = base + (6 * (first + i));
        if !spend(s, 2) {
            return false;
        }
        if bcmp(p, b, cu, pv + 3) <= 0 {
            return false;
        }
        if pw(p, pv + 3) == 5 {
            return false;
        }
        if is_succ(p, b, pv + 3, cu) {
            return false;
        }
    }
    return true;
}
pub(crate) fn fiv_run_ok(p: &[i32], first: i32, n: i32) -> bool {
    if (first < 0) || ((n < 0) || (n > (pw(p, W_N_FINTERVALS) - first))) {
        return false;
    }
    let base: i32 = sec(p, 14);
    for i in 1..n {
        let pv: i32 = base + (4 * (first + (i - 1)));
        let cu: i32 = base + (4 * (first + i));
        let ph: i32 = pw(p, pv + 2);
        let pl: i32 = pw(p, pv + 3);
        let nl: i32 = i32::wrapping_add(pl, 1);
        let mut nh: i32 = ph;
        if pl == (-1) {
            nh = i32::wrapping_add(ph, 1);
        }
        if (ph == (-1)) && (pl == (-1)) {
            return false;
        }
        if u64_cmp(pw(p, cu), pw(p, cu + 1), ph, pl) <= 0 {
            return false;
        }
        if (pw(p, cu) == (nh | 0)) && (pw(p, cu + 1) == (nl | 0)) {
            return false;
        }
    }
    return true;
}
pub(crate) fn iv_mask(p: &[i32], first: i32, n: i32, bigok: i32) -> i32 {
    // The INT class mask of a (checked) interval run.
    let base: i32 = sec(p, 13);
    let mut m: i32 = 0;
    for i in 0..n {
        let o: i32 = base + (6 * (first + i));
        let lr: i32 = pw(p, o);
        let hr: i32 = pw(p, o + 3);
        if (lr <= 3) && (hr >= 3) {
            m |= 1;
        }
        if (lr <= 2) && (hr >= 2) {
            m |= 2;
        }
        if bigok != 0 {
            if ((lr <= 1) && (hr >= 1)) || ((lr <= 4) && (hr >= 4)) {
                m |= 2048;
            }
        }
    }
    return m;
}
pub(crate) fn zero_from(p: &[i32], o: i32, k: i32) -> bool {
    // Are leaf words d_k .. d5 (o + 2 + k .. o + 7) all zero?
    for i in 2 + k..8 {
        if pw(p, o + i) != 0 {
            return false;
        }
    }
    return true;
}
pub(crate) fn leaf_mask_of(p: &[i32], b: &[u8], l: i32) -> i32 {
    // The derived mask of leaf l (fields already checked), -1 if invalid.
    let o: i32 = leaf_at(p, l);
    let k: i32 = pw(p, o) & 255;
    let fl: i32 = (pw(p, o) >> 8) & 255;
    let d0: i32 = pw(p, o + 2);
    let d1: i32 = pw(p, o + 3);
    if k == 1 {
        return 4095;
    }
    if k == 2 {
        if d0 == 6 {
            return 2112;
        }
        if d0 == 7 {
            return 1920;
        }
        return 1 << d0;
    }
    if k == 3 {
        return iv_mask(p, d0, d1, fl);
    }
    if k == 4 {
        return fl << 8;
    }
    if k == 5 {
        return 128;
    }
    if k == 6 {
        return enc_class(b, d0);
    }
    if k == 7 {
        let lr: i32 = sec(p, 15) + (2 * d0);
        return enc_class(b, pw(p, lr));
    }
    if k == 8 {
        return 8;
    }
    if (k == 9) || (k == 13) {
        return 4;
    }
    if k == 10 {
        return 1;
    }
    if k == 11 {
        if (d0 == 0) && ((d1 == 2) || (d1 == 3)) {
            return 2048;
        }
        return 64;
    }
    if k == 12 {
        let lohi: i32 = d0;
        let lolo: i32 = d1;
        let hihi: i32 = pw(p, o + 4);
        let hilo: i32 = pw(p, o + 5);
        let mut m: i32 = 0;
        if ((lohi != 0) || (hihi != 0)) || ((i32::cast_unsigned(lolo) < i32::cast_unsigned(2)) || (i32::cast_unsigned(3) < i32::cast_unsigned(hilo))) {
            m |= 64;
        }
        if ((lohi == 0) && (i32::cast_unsigned(lolo) < i32::cast_unsigned(4))) && ((hihi != 0) || (!(i32::cast_unsigned(hilo) < i32::cast_unsigned(2)))) {
            m |= 2048;
        }
        return m;
    }
    if k == 14 {
        return 16;
    }
    if k == 15 {
        return 32;
    }
    if k == 18 {
        return 4095;
    }
    return 0;
}
pub(crate) fn check_leaf(p: &[i32], b: &[u8], s: &mut [i32], l: i32) -> bool {
    let o: i32 = leaf_at(p, l);
    let w0: i32 = pw(p, o);
    let k: i32 = w0 & 255;
    let fl: i32 = (w0 >> 8) & 255;
    let d0: i32 = pw(p, o + 2);
    let d1: i32 = pw(p, o + 3);
    let d2: i32 = pw(p, o + 4);
    let d3: i32 = pw(p, o + 5);
    let d4: i32 = pw(p, o + 6);
    let nl: i32 = pw(p, W_N_LEAVES);
    let nt: i32 = pw(p, W_N_TYPESETS);
    if !spend(s, 8) {
        return false;
    }
    if ((k < 1) || (k > 18)) || ((w0 >> 16) != 0) {
        return want(s, false, o, C_LEAF);
    }
    if pw(p, o + 7) != 0 {
        return want(s, false, o, C_LEAF);
    }
    if ((k != 3) && (k != 4)) && ((k != 13) && (fl != 0)) {
        return want(s, false, o, C_LEAF);
    }
    if k == 1 {
        return want(s, zero_from(p, o, 0), o, C_LEAF);
    }
    if k == 2 {
        return want(s, ((d0 >= 0) && (d0 <= 7)) && zero_from(p, o, 1), o, C_LEAF);
    }
    if k == 3 {
        let run_ok: bool = iv_run_ok(p, b, s, d0, d1);
        return want(s, ((fl <= 1) && (d1 >= 1)) && (run_ok && zero_from(p, o, 2)), o, C_LEAF);
    }
    if k == 4 {
        if (fl < 1) || (fl > 7) {
            return want(s, false, o, C_LEAF);
        }
        if d1 == 0 {
            return want(s, zero_from(p, o, 0), o, C_LEAF);
        }
        return want(s, fiv_run_ok(p, d0, d1) && zero_from(p, o, 2), o, C_LEAF);
    }
    if k == 5 {
        return want(s, (((d0 >= 0) && (d0 <= 23)) || ((d0 >= 32) && (d0 <= 255))) && zero_from(p, o, 1), o, C_LEAF);
    }
    if k == 6 {
        return want(s, (byte_range(b, d0, d1) && (d1 >= 1)) && zero_from(p, o, 2), o, C_LEAF);
    }
    if k == 7 {
        if ((d0 < 0) || (d1 < 2)) || (d1 > (pw(p, W_N_LITREFS) - d0)) {
            return want(s, false, o, C_LEAF);
        }
        if !zero_from(p, o, 2) {
            return want(s, false, o, C_LEAF);
        }
        let lb: i32 = sec(p, 15);
        let mut cls: i32 = 0;
        for i in 0..d1 {
            let mo: i32 = pw(p, lb + (2 * (d0 + i)));
            let ml: i32 = pw(p, lb + ((2 * (d0 + i)) + 1));
            if (!byte_range(b, mo, ml)) || (ml < 1) {
                return want(s, false, o, C_LITREF);
            }
            if i == 0 {
                cls = enc_class(b, mo);
            }
            if enc_class(b, mo) != cls {
                return want(s, false, o, C_LITREF);
            }
            if i > 0 {
                let po: i32 = pw(p, lb + (2 * (d0 + (i - 1))));
                let pl: i32 = pw(p, lb + ((2 * (d0 + (i - 1))) + 1));
                if bytes_cmp(b, po, pl, mo, ml) >= 0 {
                    return want(s, false, o, C_LITREF);
                }
            }
        }
        return true;
    }
    if k == 8 {
        return want(s, (((d0 >= 0) && (d1 >= d0)) && ((d2 >= (-1)) && (d2 < pw(p, W_N_REGEXPS)))) && zero_from(p, o, 3), o, C_LEAF);
    }
    if k == 9 {
        if (d0 < 0) || (d1 < d0) {
            return want(s, false, o, C_LEAF);
        }
        if d3 == 0 {
            return want(s, zero_from(p, o, 2), o, C_LEAF);
        }
        return want(s, byte_range(b, d2, d3) && zero_from(p, o, 4), o, C_LEAF);
    }
    if k == 10 {
        if d3 == 0 {
            return want(s, (d2 == 0) && zero_from(p, o, 4), o, C_LEAF);
        }
        let run_ok2: bool = iv_run_ok(p, b, s, d2, d3);
        return want(s, run_ok2 && zero_from(p, o, 4), o, C_LEAF);
    }
    if k == 11 {
        return want(s, in_range(d2, nt) && zero_from(p, o, 3), o, C_LEAF);
    }
    if k == 12 {
        return want(s, (u64_cmp(d0, d1, d2, d3) <= 0) && (in_range(d4, nt) && zero_from(p, o, 5)), o, C_LEAF);
    }
    if k == 13 {
        return want(s, (fl <= 1) && (in_range(d0, nt) && zero_from(p, o, 1)), o, C_LEAF);
    }
    if k == 14 {
        return want(s, in_range(d0, pw(p, W_N_ARRAYS)) && zero_from(p, o, 1), o, C_LEAF);
    }
    if k == 15 {
        return want(s, in_range(d0, pw(p, W_N_MAPS)) && zero_from(p, o, 1), o, C_LEAF);
    }
    if k == 16 {
        return want(s, (in_range(d0, nl) && in_range(d1, nl)) && zero_from(p, o, 2), o, C_LEAF);
    }
    if k == 18 {
        // EXT (D140): control id, argument bytes (at least one), maximum item bytes
        return want(s, (in_range(d0, pw(p, W_N_EXTS)) && (byte_range(b, d1, d2) && (d2 >= 1))) && ((d3 >= 0) && zero_from(p, o, 4)), o, C_LEAF);
    }
    if in_range(d0, nl) && in_range(d1, nl) {
        return want(s, (leaf_kind(p, d1) == 6) && zero_from(p, o, 2), o, C_LEAF);
    }
    return want(s, false, o, C_LEAF);
}
pub(crate) fn check_leaves(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    let nl: i32 = pw(p, W_N_LEAVES);
    for l in 0..nl {
        if !check_leaf(p, b, s, l) {
            return false;
        }
    }
    // masks, derived (AND/NOT need their operands' masks: computed in a second pass)
    for l2 in 0..nl {
        let o: i32 = leaf_at(p, l2);
        let k: i32 = pw(p, o) & 255;
        if (k != 16) && (k != 17) {
            if pw(p, o + 1) != leaf_mask_of(p, b, l2) {
                return want(s, false, o + 1, C_MASK);
            }
        }
    }
    for l3 in 0..nl {
        let o3: i32 = leaf_at(p, l3);
        let k3: i32 = pw(p, o3) & 255;
        if (k3 == 16) || (k3 == 17) {
            // AND: mask(a) & mask(b), NOT: mask(target), over the operands' stored
            // masks (each verified in turn, so the whole set is consistent).
            let ma: i32 = pw(p, leaf_at(p, pw(p, o3 + 2)) + 1);
            let mb: i32 = pw(p, leaf_at(p, pw(p, o3 + 3)) + 1);
            let mut m: i32 = ma;
            if k3 == 16 {
                m = ma & mb;
            }
            if pw(p, o3 + 1) != m {
                return want(s, false, o3 + 1, C_MASK);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn check_keys(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    let base: i32 = sec(p, 4);
    let n: i32 = pw(p, W_N_KEYS);
    for i in 0..n {
        let o: i32 = base + (2 * i);
        let off: i32 = pw(p, o);
        let len: i32 = pw(p, o + 1);
        if !spend(s, 2 + (len / 8)) {
            return false;
        }
        if (!byte_range(b, off, len)) || (len < 1) {
            return want(s, false, o, C_KEY);
        }
        let m: i32 = (i32::cast_unsigned(b[(off) as usize] as i32) >> 5).cast_signed();
        let he: i32 = head_end(b, off, off + len);
        if he < 0 {
            return want(s, false, o, C_KEY);
        }
        if m <= 1 {
            if he != (off + len) {
                return want(s, false, o, C_KEY);
            }
        } else {
            if m != 3 {
                return want(s, false, o, C_KEY);
            }
            let cl: i32 = head_len_arg(b, off);
            if (cl < 0) || ((he + cl) != (off + len)) {
                return want(s, false, o, C_KEY);
            }
            if !utf8_ok(b, he, off + len) {
                return want(s, false, o, C_UTF8);
            }
        }
        if i > 0 {
            if bytes_cmp(b, pw(p, o - 2), pw(p, o - 1), off, len) >= 0 {
                return want(s, false, o, C_KEY);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn check_rules(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    let base: i32 = sec(p, 0);
    let n: i32 = pw(p, W_N_RULES);
    for i in 0..n {
        let o: i32 = base + (5 * i);
        let off: i32 = pw(p, o);
        let len: i32 = pw(p, o + 1);
        if !spend(s, 2 + (len / 8)) {
            return false;
        }
        if (!byte_range(b, off, len)) || (len < 1) {
            return want(s, false, o, C_RULE);
        }
        if !utf8_ok(b, off, off + len) {
            return want(s, false, o, C_UTF8);
        }
        if i > 0 {
            if bytes_cmp(b, pw(p, o - 5), pw(p, o - 4), off, len) >= 0 {
                return want(s, false, o, C_RULE);
            }
        }
        if !in_range(pw(p, o + 2), pw(p, W_N_TYPESETS)) {
            return want(s, false, o, C_RULE);
        }
        if !in_range(pw(p, o + 3), pw(p, W_N_CHAINS)) {
            return want(s, false, o, C_RULE);
        }
    }
    return !failed(s);
}
pub(crate) fn tb(s: &[i32]) -> i32 {
    return MARKS + (2 * s[(VM_MARK_CAP) as usize]);
}
pub(crate) fn tg(s: &[i32], i: i32) -> i32 {
    return s[(tb(s) + i) as usize];
}
pub(crate) fn tset(s: &mut [i32], i: i32, v: i32) {
    s[(tb(s) + i) as usize] = v;
}
pub(crate) fn sadd(a: i32, b: i32) -> i32 {
    if (a == INF) || (b == INF) {
        return INF;
    }
    if a > (INF - b) {
        return INF;
    }
    return a + b;
}
pub(crate) fn smul(a: i32, b: i32) -> i32 {
    if (a == 0) || (b == 0) {
        return 0;
    }
    if (a == INF) || (b == INF) {
        return INF;
    }
    if a > (INF / b) {
        return INF;
    }
    return a * b;
}
pub(crate) fn imax(a: i32, b: i32) -> i32 {
    if a > b {
        return a;
    }
    return b;
}
pub(crate) fn more_budget(s: &mut [i32], units: i32) -> bool {
    // Raise the verify budget by units (saturating) before a fixed point.
    s[(V_BUDGET) as usize] = sadd(s[(V_BUDGET) as usize], units);
    return true;
}
pub(crate) fn peg_at(p: &[i32], g: i32) -> i32 {
    return rec(p, 5, g);
}
pub(crate) fn pnw(p: &[i32], o: i32, i: i32, w: i32) -> i32 {
    return pw(p, (o + PEG_HDR) + ((5 * i) + w));
}
pub(crate) fn pkid(p: &[i32], o: i32, i: i32, j: i32) -> i32 {
    // Kid j of SEQ / CHOICE node i of the program at o.
    return pw(p, ((o + PEG_HDR) + (5 * pw(p, o + 1))) + (pnw(p, o, i, 1) + j));
}
pub(crate) fn counts_ok(lo: i32, hi: i32) -> bool {
    // program-2 §3 Counts: 0 <= min <= 2^24, 1 <= max, max INF or below 2^24,
    // min <= max.
    if (lo < 0) || (lo > COUNT_SAT) {
        return false;
    }
    if hi < 1 {
        return false;
    }
    if (hi != INF) && (hi >= COUNT_SAT) {
        return false;
    }
    return lo <= hi;
}
pub(crate) fn peg_count(p: &[i32], o: i32, op: i32) -> i32 {
    // Nodes of the program at o with this op.
    let mut c: i32 = 0;
    for i in 0..pw(p, o + 1) {
        if pnw(p, o, i, 0) == op {
            c += 1;
        }
    }
    return c;
}
pub(crate) fn peg_nullable(p: &[i32], s: &mut [i32], o: i32, n: i32, calls: i32) -> bool {
    // nullable as a least fixed point (TEMP[0, n)): rounds in reverse id order
    // until nothing changes; one round without CALLs.
    for z in 0..n {
        tset(s, z, 0);
    }
    loop {
        let mut changed: bool = false;
        if !spend(s, n) {
            return false;
        }
        let mut i: i32 = n - 1;
        while i >= 0 {
            let op: i32 = pnw(p, o, i, 0);
            let mut nu: i32 = 0;
            if op == P_EMPTY {
                nu = 1;
            }
            if (op == P_MEMBER) && (pnw(p, o, i, 2) == 0) {
                nu = 1;
            }
            if op == P_CALL {
                nu = tg(s, pnw(p, o, i, 1));
            }
            if op == P_REP {
                if (pnw(p, o, i, 2) == 0) || (tg(s, pnw(p, o, i, 1)) != 0) {
                    nu = 1;
                }
            }
            if op == P_CHOICE {
                for j in 0..pnw(p, o, i, 2) {
                    if tg(s, pkid(p, o, i, j)) != 0 {
                        nu = 1;
                    }
                }
            }
            if op == P_SEQ {
                nu = 1;
                for j2 in 0..pnw(p, o, i, 2) {
                    if tg(s, pkid(p, o, i, j2)) == 0 {
                        nu = 0;
                    }
                }
            }
            if (nu != 0) && (tg(s, i) == 0) {
                tset(s, i, 1);
                changed = true;
            }
            i -= 1;
        }
        if (!changed) || (calls == 0) {
            return true;
        }
    }
}
pub(crate) fn left_edge(p: &[i32], s: &[i32], o: i32, u: i32, j: i32) -> i32 {
    // Edge j of node u in the left graph (program-2 §5.3), or -1.
    let op: i32 = pnw(p, o, u, 0);
    if op == P_SEQ {
        if j >= pnw(p, o, u, 2) {
            return -1;
        }
        if (j > 0) && (tg(s, pkid(p, o, u, j - 1)) == 0) {
            return -1;
        }
        return pkid(p, o, u, j);
    }
    if op == P_CHOICE {
        if j >= pnw(p, o, u, 2) {
            return -1;
        }
        return pkid(p, o, u, j);
    }
    if ((op == P_REP) || (op == P_CALL)) && (j == 0) {
        return pnw(p, o, u, 1);
    }
    return -1;
}
pub(crate) fn no_left_recursion(p: &[i32], s: &mut [i32], o: i32, n: i32) -> bool {
    // No cycle in the left graph (CALL cycles reachable through nullable
    // prefixes): iterative DFS, colours TEMP[4n..), cursors TEMP[5n..), stack
    // TEMP[6n..). Needs the nullable words.
    for z in 0..n {
        tset(s, (4 * n) + z, 0);
    }
    for st in 0..n {
        if tg(s, (4 * n) + st) == 0 {
            let mut sp: i32 = 1;
            tset(s, 6 * n, st);
            tset(s, (4 * n) + st, 1);
            tset(s, (5 * n) + st, 0);
            while sp > 0 {
                if !spend(s, 1) {
                    return false;
                }
                let u: i32 = tg(s, (6 * n) + (sp - 1));
                let j: i32 = tg(s, (5 * n) + u);
                let v: i32 = left_edge(p, s, o, u, j);
                if v < 0 {
                    tset(s, (4 * n) + u, 2);
                    sp -= 1;
                } else {
                    tset(s, (5 * n) + u, j + 1);
                    if tg(s, (4 * n) + v) == 1 {
                        return false;
                    }
                    if tg(s, (4 * n) + v) == 0 {
                        if sp >= n {
                            return false;
                        }
                        tset(s, (4 * n) + v, 1);
                        tset(s, (5 * n) + v, 0);
                        tset(s, (6 * n) + sp, v);
                        sp += 1;
                    }
                }
            }
        }
    }
    return true;
}
pub(crate) fn check_peg(p: &[i32], s: &mut [i32], g: i32) -> bool {
    // One program: node fields and counts, a tree through kids and REP children
    // (each non-root node referenced once, by a smaller id), positions and
    // members numbered in node order, the map normal form (no foldable REP of
    // a MEMBER, §3.3), no left recursion, and the derived fields: n_calls,
    // flags bit 0, depth, B and the array tier (map tiers: check-map).
    let o: i32 = peg_at(p, g);
    let kind: i32 = pw(p, o);
    let n: i32 = pw(p, o + 1);
    let nk: i32 = pw(p, o + 2);
    let mut npos: i32 = 0;
    let mut nmem: i32 = 0;
    let mut calls: i32 = 0;
    let mut sumk: i32 = 0;
    if !spend(s, (5 * n) + nk) {
        return false;
    }
    if (kind < 0) || (kind > 1) {
        return want(s, false, o, C_PEG);
    }
    if pw(p, o + 5) != 0 {
        return want(s, false, o + 5, C_PEG);
    }
    for z in 0..n {
        tset(s, (4 * n) + z, 0);
    }
    for i in 0..n {
        let at: i32 = (o + PEG_HDR) + (5 * i);
        let op: i32 = pw(p, at);
        let a: i32 = pw(p, at + 1);
        let b: i32 = pw(p, at + 2);
        let c: i32 = pw(p, at + 3);
        if pw(p, at + 4) != (-1) {
            return want(s, false, at, C_PEG);
        }
        if (op < 0) || (op > 7) {
            return want(s, false, at, C_PEG);
        }
        if op == P_EMPTY {
            if (a != 0) || ((b != 0) || (c != 0)) {
                return want(s, false, at, C_PEG);
            }
        }
        if op == P_FAIL {
            if (a != 0) || ((b < (-1)) || (c != 0)) {
                return want(s, false, at, C_PEG);
            }
        }
        if op == P_ENTRY {
            if (kind != 0) || ((a != npos) || ((b != 0) || (c != 0))) {
                return want(s, false, at, C_PEG);
            }
            npos += 1;
        }
        if op == P_MEMBER {
            if (kind != 1) || ((a != nmem) || (!counts_ok(b, c))) {
                return want(s, false, at, C_PEG);
            }
            nmem += 1;
        }
        if (op == P_SEQ) || (op == P_CHOICE) {
            if ((c != 0) || (b < 2)) || ((a < 0) || (a > (nk - b))) {
                return want(s, false, at, C_PEG);
            }
            sumk += b;
            for j in 0..b {
                let k: i32 = pkid(p, o, i, j);
                if (!in_range(k, n)) || (k <= i) {
                    return want(s, false, at, C_PEG);
                }
                tset(s, (4 * n) + k, tg(s, (4 * n) + k) + 1);
            }
        }
        if op == P_REP {
            if (!counts_ok(b, c)) || ((!in_range(a, n)) || (a <= i)) {
                return want(s, false, at, C_PEG);
            }
            tset(s, (4 * n) + a, tg(s, (4 * n) + a) + 1);
            if (kind == 1) && (pnw(p, o, a, 0) == P_MEMBER) {
                // the fold table leaves no REP of a MEMBER(1, 1) or MEMBER(k, INF)
                // it would rewrite
                let mk: i32 = pnw(p, o, a, 2);
                let mm: i32 = pnw(p, o, a, 3);
                if (mk == 1) && (mm == 1) {
                    return want(s, false, at, C_PEG);
                }
                if (mm == INF) && ((mk == 0) || (((mk == 1) && (b <= 1)) || ((mk >= 1) && (b >= 2)))) {
                    return want(s, false, at, C_PEG);
                }
            }
        }
        if op == P_CALL {
            if ((b != 0) || (c != 0)) || (!in_range(a, n)) {
                return want(s, false, at, C_PEG);
            }
            calls += 1;
        }
    }
    if sumk != nk {
        return want(s, false, o + 2, C_PEG);
    }
    for i2 in 1..n {
        if tg(s, (4 * n) + i2) != 1 {
            return want(s, false, (o + PEG_HDR) + (5 * i2), C_PEG);
        }
    }
    // derived: n_calls, flags (arrays: bit 0 only; maps: bits 1-2 by check-map)
    if pw(p, o + 8) != calls {
        return want(s, false, o + 8, C_DERIVED);
    }
    let fl: i32 = pw(p, o + 7);
    let mut rbit: i32 = 0;
    if calls > 0 {
        rbit = 1;
    }
    if (fl & 1) != rbit {
        return want(s, false, o + 7, C_DERIVED);
    }
    if (kind == 0) && (fl != rbit) {
        return want(s, false, o + 7, C_DERIVED);
    }
    if (kind == 1) && ((fl & (!7)) != 0) {
        return want(s, false, o + 7, C_DERIVED);
    }
    // lengths (TEMP: ml at n.., FL at 2n.., height at 3n..), B, depth
    let mut bmax: i32 = 0;
    if !spend(s, 2 * n) {
        return false;
    }
    let mut i3: i32 = n - 1;
    while i3 >= 0 {
        let op3: i32 = pnw(p, o, i3, 0);
        let mut ml: i32 = 0;
        let mut flv: i32 = 0;
        let mut ht: i32 = 1;
        if op3 == P_EMPTY {
            flv = -1;
        }
        if (op3 == P_ENTRY) || (op3 == P_MEMBER) {
            ml = 1;
        }
        if (op3 == P_MEMBER) && (pnw(p, o, i3, 2) == 0) {
            flv = -1;
        }
        if op3 == P_CALL {
            ml = INF;
            flv = INF;
        }
        if op3 == P_SEQ {
            let mut pre: i32 = 0;
            flv = -1;
            for j3 in 0..pnw(p, o, i3, 2) {
                let k3: i32 = pkid(p, o, i3, j3);
                let kfl: i32 = tg(s, (2 * n) + k3);
                if kfl != (-1) {
                    flv = imax(flv, sadd(pre, kfl));
                }
                pre = sadd(pre, tg(s, n + k3));
                ht = imax(ht, 1 + tg(s, (3 * n) + k3));
            }
            ml = pre;
        }
        if op3 == P_CHOICE {
            let kc: i32 = pnw(p, o, i3, 2);
            let mut nofail: bool = false;
            for j4 in 0..kc {
                let k4: i32 = pkid(p, o, i3, j4);
                let kfl4: i32 = tg(s, (2 * n) + k4);
                ml = imax(ml, tg(s, n + k4));
                if kfl4 == (-1) {
                    nofail = true;
                } else {
                    flv = imax(flv, kfl4);
                }
                if (j4 < (kc - 1)) && (kfl4 != (-1)) {
                    bmax = imax(bmax, kfl4);
                }
                ht = imax(ht, 1 + tg(s, (3 * n) + k4));
            }
            if nofail {
                flv = -1;
            }
        }
        if op3 == P_REP {
            let ch: i32 = pnw(p, o, i3, 1);
            let lo: i32 = pnw(p, o, i3, 2);
            let hi: i32 = pnw(p, o, i3, 3);
            let cml: i32 = tg(s, n + ch);
            let cfl: i32 = tg(s, (2 * n) + ch);
            ml = smul(hi, cml);
            if (lo == 0) || (cfl == (-1)) {
                flv = -1;
            } else {
                flv = sadd(smul(lo - 1, cml), cfl);
            }
            if cfl != (-1) {
                bmax = imax(bmax, cfl);
            }
            ht = 1 + tg(s, (3 * n) + ch);
        }
        tset(s, n + i3, ml);
        tset(s, (2 * n) + i3, flv);
        tset(s, (3 * n) + i3, ht);
        i3 -= 1;
    }
    if pw(p, o + 6) != tg(s, 3 * n) {
        return want(s, false, o + 6, C_DERIVED);
    }
    // nullable and left recursion (budget raised by the fixed point's bound)
    more_budget(s, smul(4, smul(calls + 2, n)));
    if !peg_nullable(p, s, o, n, calls) {
        return false;
    }
    if !no_left_recursion(p, s, o, n) {
        return want(s, false, o, C_RECURSION);
    }
    // the array tier and B; maps keep B = 0
    let w: i32 = (npos + 31) >> 5;
    let mut tier: i32 = TIER_A2;
    let mut bs: i32 = 0;
    if calls == 0 {
        if bmax == 0 {
            tier = TIER_A0;
        }
        if (bmax > 0) && ((bmax < RING_WORDS) && (((bmax + 1) * w) <= RING_WORDS)) {
            tier = TIER_A1;
            bs = bmax;
        }
    }
    if kind == 1 {
        bs = 0;
    }
    if pw(p, o + 4) != bs {
        return want(s, false, o + 4, C_DERIVED);
    }
    if (kind == 0) && (pw(p, o + 3) != tier) {
        return want(s, false, o + 3, C_DERIVED);
    }
    return !failed(s);
}
pub(crate) fn check_pegs(p: &[i32], s: &mut [i32]) -> bool {
    for g in 0..pw(p, W_N_PEGS) {
        if !check_peg(p, s, g) {
            return false;
        }
    }
    return true;
}
pub(crate) fn fail_prov_ok(p: &[i32], o: i32, lim: i32) -> bool {
    // Every FAIL's provenance of the program at o is -1 or below lim.
    for i in 0..pw(p, o + 1) {
        if (pnw(p, o, i, 0) == P_FAIL) && (pnw(p, o, i, 2) >= lim) {
            return false;
        }
    }
    return true;
}
pub(crate) fn ceil32(n: i32) -> i32 {
    return (n + 31) >> 5;
}
pub(crate) fn map_lits(p: &[i32], o: i32) -> i32 {
    // Literal members (key id >= 0) of the map table at o.
    let mut c: i32 = 0;
    for i in 0..pw(p, o + 1) {
        if pw(p, (o + 8) + (5 * i)) >= 0 {
            c += 1;
        }
    }
    return c;
}
pub(crate) fn map_namers_max(p: &[i32], o: i32) -> i32 {
    let nm: i32 = pw(p, o + 1);
    let nn: i32 = pw(p, o + 2);
    let nb: i32 = (o + 8) + (5 * nm);
    let mut mx: i32 = 0;
    for q in 0..nn {
        if pw(p, nb + ((3 * q) + 2)) > mx {
            mx = pw(p, nb + ((3 * q) + 2));
        }
    }
    return mx;
}
pub(crate) fn check_map(p: &[i32], s: &mut [i32], m: i32) -> bool {
    let o: i32 = rec(p, 7, m);
    let peg: i32 = pw(p, o);
    let nm: i32 = pw(p, o + 1);
    let nn: i32 = pw(p, o + 2);
    let kts: i32 = pw(p, o + 3);
    let nr: i32 = pw(p, o + 6);
    let mb: i32 = o + 8;
    let nb: i32 = mb + (5 * nm);
    let nlit: i32 = map_lits(p, o);
    let rb: i32 = (nb + (3 * nn)) + nlit;
    let nt: i32 = pw(p, W_N_TYPESETS);
    let nkeys: i32 = pw(p, W_N_KEYS);
    if !spend(s, (5 * nm) + ((3 * nn) + (nlit + nr))) {
        return false;
    }
    if !in_range(peg, pw(p, W_N_PEGS)) {
        return want(s, false, o, C_MAP);
    }
    let po: i32 = peg_at(p, peg);
    let pn: i32 = pw(p, po + 1);
    if pw(p, po) != 1 {
        return want(s, false, o, C_MAP);
    }
    if peg_count(p, po, P_MEMBER) != nm {
        return want(s, false, o + 1, C_MAP);
    }
    if !fail_prov_ok(p, po, nm) {
        return want(s, false, o, C_MAP);
    }
    // members: key id or key typeset, value typeset, cut
    for i in 0..nm {
        let e: i32 = mb + (5 * i);
        let kid: i32 = pw(p, e);
        let kt: i32 = pw(p, e + 1);
        if kid >= 0 {
            if (!in_range(kid, nkeys)) || (kt != (-1)) {
                return want(s, false, e, C_MAP);
            }
        } else if (kid != (-1)) || (!in_range(kt, nt)) {
            return want(s, false, e, C_MAP);
        }
        if !in_range(pw(p, e + 2), nt) {
            return want(s, false, e, C_MAP);
        }
        if (pw(p, e + 4) < 0) || (pw(p, e + 4) > 1) {
            return want(s, false, e, C_MAP);
        }
    }
    // classes [D]: the root (or the root SEQ's kids) marked in TEMP
    for z in 0..pn {
        tset(s, z, 0);
    }
    let rop: i32 = pnw(p, po, 0, 0);
    let mut flat: bool = (rop == P_EMPTY) || (rop == P_MEMBER);
    if rop == P_MEMBER {
        tset(s, 0, 1);
    }
    if rop == P_SEQ {
        flat = true;
        for j in 0..pnw(p, po, 0, 2) {
            let k: i32 = pkid(p, po, 0, j);
            tset(s, k, 1);
            if pnw(p, po, k, 0) != P_MEMBER {
                flat = false;
            }
        }
    }
    let mut anyos: bool = false;
    let mut anycut: bool = false;
    let mut class2: bool = false;
    let mut ri: i32 = 0;
    for i2 in 0..pn {
        if pnw(p, po, i2, 0) == P_MEMBER {
            let mi: i32 = pnw(p, po, i2, 1);
            let e2: i32 = mb + (5 * mi);
            let lit: bool = pw(p, e2) >= 0;
            let mx: i32 = pnw(p, po, i2, 3);
            let mut cls: i32 = 0;
            if pw(p, e2 + 4) != 0 {
                anycut = true;
            }
            if !lit {
                if mx != INF {
                    anyos = true;
                }
                if (tg(s, i2) == 1) && (mx == INF) {
                    cls = 1;
                } else {
                    cls = 2;
                }
            }
            if cls == 2 {
                class2 = true;
            }
            if pw(p, e2 + 3) != cls {
                return want(s, false, e2, C_DERIVED);
            }
            if cls == 1 {
                if (ri >= nr) || (pw(p, rb + ri) != mi) {
                    return want(s, false, o + 6, C_DERIVED);
                }
                ri += 1;
            }
        }
    }
    if ri != nr {
        return want(s, false, o + 6, C_DERIVED);
    }
    // tier and flags [D]
    let mut tier: i32 = TIER_T;
    let mut pf: i32 = 0;
    let mut mf: i32 = 0;
    if (!class2) && ((!anyos) && (pw(p, po + 8) == 0)) {
        tier = TIER_S;
    }
    if flat && (!anyos) {
        tier = TIER_F;
    }
    if anyos {
        pf |= 2;
        mf |= 1;
    }
    if anycut {
        pf |= 4;
        mf |= 2;
    }
    if pw(p, po + 3) != tier {
        return want(s, false, po + 3, C_DERIVED);
    }
    if (pw(p, po + 7) & 6) != pf {
        return want(s, false, po + 7, C_DERIVED);
    }
    if pw(p, o + 7) != mf {
        return want(s, false, o + 7, C_DERIVED);
    }
    // named: by key id; namers ascending, naming their key; all literal members
    let mut next: i32 = 0;
    let mut nmax: i32 = 0;
    for q in 0..nn {
        let qo: i32 = nb + (3 * q);
        let key: i32 = pw(p, qo);
        let first: i32 = pw(p, qo + 1);
        let cnt: i32 = pw(p, qo + 2);
        if !in_range(key, nkeys) {
            return want(s, false, qo, C_MAP);
        }
        if (q > 0) && (key <= pw(p, qo - 3)) {
            return want(s, false, qo, C_MAP);
        }
        if (first != next) || ((cnt < 1) || (cnt > (nlit - first))) {
            return want(s, false, qo, C_MAP);
        }
        if cnt > nmax {
            nmax = cnt;
        }
        for r in 0..cnt {
            let na: i32 = (nb + (3 * nn)) + (first + r);
            let mid: i32 = pw(p, na);
            if !in_range(mid, nm) {
                return want(s, false, na, C_MAP);
            }
            if (r > 0) && (mid <= pw(p, na - 1)) {
                return want(s, false, na, C_MAP);
            }
            if pw(p, mb + (5 * mid)) != key {
                return want(s, false, na, C_MAP);
            }
        }
        next = first + cnt;
    }
    if next != nlit {
        return want(s, false, o + 2, C_MAP);
    }
    // slot_words, rec_words [D]
    let mut sw: i32 = 0;
    let mut rw: i32 = 0;
    if tier == TIER_S {
        sw = (2 + ceil32(nmax)) + (2 * ceil32(nr));
    }
    if tier == TIER_T {
        rw = 2 + ceil32(2 * nm);
    }
    if pw(p, o + 4) != sw {
        return want(s, false, o + 4, C_DERIVED);
    }
    if pw(p, o + 5) != rw {
        return want(s, false, o + 5, C_DERIVED);
    }
    // key_ts [D]: the union of the non-literal members' key typesets, or -1
    let e3: i32 = epoch(s);
    let mut distinct: i32 = 0;
    let mut any: bool = false;
    for i3 in 0..nm {
        let kt3: i32 = pw(p, (mb + (5 * i3)) + 1);
        if kt3 >= 0 {
            any = true;
            let to: i32 = rec(p, 2, kt3);
            let tn: i32 = pw(p, to);
            if !spend(s, tn) {
                return false;
            }
            for a in 0..tn {
                let l: i32 = pw(p, to + (2 + a));
                if mark_get(s, l) != e3 {
                    mark_set(s, l, e3);
                    distinct += 1;
                }
            }
        }
    }
    if !any {
        if kts != (-1) {
            return want(s, false, o + 3, C_DERIVED);
        }
    } else {
        if !in_range(kts, nt) {
            return want(s, false, o + 3, C_DERIVED);
        }
        let ko: i32 = rec(p, 2, kts);
        let kn: i32 = pw(p, ko);
        if kn != distinct {
            return want(s, false, o + 3, C_DERIVED);
        }
        for a2 in 0..kn {
            if mark_get(s, pw(p, ko + (2 + a2))) != e3 {
                return want(s, false, o + 3, C_DERIVED);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn check_maps(p: &[i32], s: &mut [i32]) -> bool {
    for m in 0..pw(p, W_N_MAPS) {
        if !check_map(p, s, m) {
            return false;
        }
    }
    return true;
}
pub(crate) fn vset_or(s: &mut [i32], dst: i32, src: i32, w: i32) -> bool {
    // TEMP[dst..dst+w) |= TEMP[src..src+w); did it grow?
    let mut grew: bool = false;
    for k in 0..w {
        let a: i32 = tg(s, dst + k);
        let c: i32 = a | tg(s, src + k);
        if c != a {
            tset(s, dst + k, c);
            grew = true;
        }
    }
    return grew;
}
pub(crate) fn vset_bit(s: &mut [i32], dst: i32, q: i32) -> bool {
    let at: i32 = dst + (q >> 5);
    let a: i32 = tg(s, at);
    let c: i32 = a | (1 << (q & 31));
    if c == a {
        return false;
    }
    tset(s, at, c);
    return true;
}
pub(crate) fn array_sets(p: &[i32], s: &mut [i32], o: i32, n: i32, w: i32, base: i32, calls: i32) -> bool {
    // first / last (2w words per node at TEMP[base..)) and nullable (TEMP[0, n))
    // as least fixed points, exactly as the compiler builds them.
    for z in 0..n {
        tset(s, z, 0);
    }
    for z2 in 0..(n + 1) * (2 * w) {
        tset(s, base + z2, 0);
    }
    loop {
        let mut changed: bool = false;
        if !spend(s, n * (1 + (2 * w))) {
            return false;
        }
        let mut i: i32 = n - 1;
        while i >= 0 {
            let op: i32 = pnw(p, o, i, 0);
            let fo: i32 = base + (i * (2 * w));
            let lo: i32 = fo + w;
            let mut nu: i32 = 0;
            if op == P_EMPTY {
                nu = 1;
            }
            if op == P_ENTRY {
                if vset_bit(s, fo, pnw(p, o, i, 1)) {
                    changed = true;
                }
                if vset_bit(s, lo, pnw(p, o, i, 1)) {
                    changed = true;
                }
            }
            if (op == P_CALL) || (op == P_REP) {
                let t: i32 = pnw(p, o, i, 1);
                let tf: i32 = base + (t * (2 * w));
                if op == P_CALL {
                    nu = tg(s, t);
                }
                if (op == P_REP) && ((pnw(p, o, i, 2) == 0) || (tg(s, t) != 0)) {
                    nu = 1;
                }
                if vset_or(s, fo, tf, w) {
                    changed = true;
                }
                if vset_or(s, lo, tf + w, w) {
                    changed = true;
                }
            }
            if op == P_CHOICE {
                for j in 0..pnw(p, o, i, 2) {
                    let k: i32 = pkid(p, o, i, j);
                    let kf: i32 = base + (k * (2 * w));
                    if tg(s, k) != 0 {
                        nu = 1;
                    }
                    if vset_or(s, fo, kf, w) {
                        changed = true;
                    }
                    if vset_or(s, lo, kf + w, w) {
                        changed = true;
                    }
                }
            }
            if op == P_SEQ {
                let kc: i32 = pnw(p, o, i, 2);
                let mut fdone: bool = false;
                nu = 1;
                for j2 in 0..kc {
                    let k2: i32 = pkid(p, o, i, j2);
                    if !fdone {
                        if vset_or(s, fo, base + (k2 * (2 * w)), w) {
                            changed = true;
                        }
                    }
                    if tg(s, k2) == 0 {
                        nu = 0;
                        fdone = true;
                    }
                }
                let mut j3: i32 = kc - 1;
                while j3 >= 0 {
                    let k3: i32 = pkid(p, o, i, j3);
                    if vset_or(s, lo, (base + (k3 * (2 * w))) + w, w) {
                        changed = true;
                    }
                    if tg(s, k3) == 0 {
                        j3 = 0;
                    }
                    j3 -= 1;
                }
            }
            if (nu != 0) && (tg(s, i) == 0) {
                tset(s, i, 1);
                changed = true;
            }
            i -= 1;
        }
        if (!changed) || (calls == 0) {
            return true;
        }
    }
}
pub(crate) fn varr_edges(s: &mut [i32], src: i32, dst: i32, w: i32, fol: i32) -> bool {
    // follow[q] |= TEMP[dst..) for every q in TEMP[src..).
    for k in 0..w {
        let v: i32 = tg(s, src + k);
        if v != 0 {
            for bit in 0..32 {
                if ((i32::cast_unsigned(v) >> bit).cast_signed() & 1) != 0 {
                    let q: i32 = (k * 32) + bit;
                    if !spend(s, w) {
                        return false;
                    }
                    for x in 0..w {
                        let fa: i32 = fol + ((q * w) + x);
                        tset(s, fa, tg(s, fa) | tg(s, dst + x));
                    }
                }
            }
        }
    }
    return true;
}
pub(crate) fn check_arrays(p: &[i32], s: &mut [i32]) -> bool {
    let na: i32 = pw(p, W_N_ARRAYS);
    let nt: i32 = pw(p, W_N_TYPESETS);
    for a in 0..na {
        let o: i32 = rec(p, 9, a);
        let npos: i32 = pw(p, o);
        let w: i32 = pw(p, o + 1);
        let peg: i32 = pw(p, o + 2);
        let fb: i32 = o + 4;
        let pb: i32 = fb + w;
        let flb: i32 = pb + npos;
        if !spend(s, npos + (npos * w)) {
            return false;
        }
        if pw(p, o + 3) != 0 {
            return want(s, false, o + 3, C_ARRAY);
        }
        if !in_range(peg, pw(p, W_N_PEGS)) {
            return want(s, false, o + 2, C_ARRAY);
        }
        let po: i32 = peg_at(p, peg);
        let n: i32 = pw(p, po + 1);
        let calls: i32 = pw(p, po + 8);
        let base: i32 = 7 * n;
        let fol: i32 = base + ((n + 1) * (2 * w));
        if pw(p, po) != 0 {
            return want(s, false, o + 2, C_ARRAY);
        }
        if peg_count(p, po, P_ENTRY) != npos {
            return want(s, false, o, C_ARRAY);
        }
        if !fail_prov_ok(p, po, npos) {
            return want(s, false, o + 2, C_ARRAY);
        }
        for q in 0..npos {
            if !in_range(pw(p, pb + q), nt) {
                return want(s, false, pb + q, C_ARRAY);
            }
        }
        // first and follow [D]: the relaxed automaton recomputed (program-2 §4)
        more_budget(s, smul(4, sadd(smul(calls + 2, smul(n, 2 + (2 * w))), smul(n, smul(npos, w)))));
        if !array_sets(p, s, po, n, w, base, calls) {
            return false;
        }
        for z in 0..npos * w {
            tset(s, fol + z, 0);
        }
        let acc: i32 = base + (n * (2 * w));
        for i in 0..n {
            let op: i32 = pnw(p, po, i, 0);
            if op == P_SEQ {
                let kc: i32 = pnw(p, po, i, 2);
                let k0: i32 = pkid(p, po, i, 0);
                for z2 in 0..w {
                    tset(s, acc + z2, 0);
                }
                vset_or(s, acc, (base + (k0 * (2 * w))) + w, w);
                for j in 1..kc {
                    let kj: i32 = pkid(p, po, i, j);
                    let kp: i32 = pkid(p, po, i, j - 1);
                    if j > 1 {
                        if tg(s, kp) == 0 {
                            for z3 in 0..w {
                                tset(s, acc + z3, 0);
                            }
                        }
                        vset_or(s, acc, (base + (kp * (2 * w))) + w, w);
                    }
                    if !varr_edges(s, acc, base + (kj * (2 * w)), w, fol) {
                        return false;
                    }
                }
            }
            if (op == P_REP) && (pnw(p, po, i, 3) >= 2) {
                let ch: i32 = pnw(p, po, i, 1);
                let cf: i32 = base + (ch * (2 * w));
                if !varr_edges(s, cf + w, cf, w, fol) {
                    return false;
                }
            }
        }
        for k in 0..w {
            if pw(p, fb + k) != tg(s, base + k) {
                return want(s, false, fb + k, C_DERIVED);
            }
        }
        for k2 in 0..npos * w {
            if pw(p, flb + k2) != tg(s, fol + k2) {
                return want(s, false, flb + k2, C_DERIVED);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn act_words(ncalls: i32, depth: i32) -> i32 {
    let a: i32 = sadd(3, smul(8, depth));
    let x: i32 = smul(smul(ncalls, a), 64);
    if x == INF {
        return INF;
    }
    return (x + 53) / 54;
}
pub(crate) fn leaf_peg(p: &[i32], l: i32) -> i32 {
    // The program offset of a (verified) ARRAY or MAP leaf.
    let o: i32 = leaf_at(p, l);
    let k: i32 = pw(p, o) & 255;
    if k == 15 {
        return peg_at(p, pw(p, rec(p, 7, pw(p, o + 2))));
    }
    return peg_at(p, pw(p, rec(p, 9, pw(p, o + 2)) + 2));
}
pub(crate) fn leaf_block(p: &[i32], l: i32) -> i32 {
    // MAPWORDS / ARRWORDS (program-2 §5.2, §6.3) of a verified leaf.
    let o: i32 = leaf_at(p, l);
    let k: i32 = pw(p, o) & 255;
    let po: i32 = leaf_peg(p, l);
    let tier: i32 = pw(p, po + 3);
    let depth: i32 = pw(p, po + 6);
    let calls: i32 = pw(p, po + 8);
    if k == 15 {
        let mo: i32 = rec(p, 7, pw(p, o + 2));
        let nm: i32 = pw(p, mo + 1);
        let nn: i32 = pw(p, mo + 2);
        let mut mw: i32 = 16 + (4 * nm);
        if calls == 0 {
            mw += 8 * depth;
        }
        if tier == TIER_S {
            mw += nn * pw(p, mo + 4);
        }
        if tier == TIER_T {
            mw += nn;
        }
        return mw;
    }
    let ao: i32 = rec(p, 9, pw(p, o + 2));
    let w: i32 = pw(p, ao + 1);
    let mut aw: i32 = 14 + (2 * w);
    if calls == 0 {
        aw += 4 * depth;
    }
    if tier == TIER_A1 {
        aw += (pw(p, po + 4) + 1) * w;
    }
    return aw;
}
pub(crate) fn leaf_recwords(p: &[i32], l: i32) -> i32 {
    // Record words of an A2 array (W) or T map (rec_words), else 0.
    let o: i32 = leaf_at(p, l);
    let k: i32 = pw(p, o) & 255;
    let po: i32 = leaf_peg(p, l);
    let tier: i32 = pw(p, po + 3);
    if (k == 15) && (tier == TIER_T) {
        return pw(p, rec(p, 7, pw(p, o + 2)) + 5);
    }
    if (k == 14) && (tier == TIER_A2) {
        return pw(p, rec(p, 9, pw(p, o + 2)) + 1);
    }
    return 0;
}
pub(crate) fn row_clean(p: &[i32], at: i32, w: i32, npos: i32) -> bool {
    // Bits >= npos of the w-word bitset at `at` are zero.
    if w == 0 {
        return true;
    }
    let used: i32 = npos - (32 * (w - 1));
    if used < 32 {
        let hi: i32 = pw(p, at + (w - 1));
        if (i32::cast_unsigned(hi) >> used).cast_signed() != 0 {
            return false;
        }
    }
    return true;
}
pub(crate) fn check_regexps(p: &[i32], s: &mut [i32]) -> bool {
    let nr: i32 = pw(p, W_N_REGEXPS);
    for r in 0..nr {
        let o: i32 = rec(p, 11, r);
        let npos: i32 = pw(p, o);
        let w: i32 = pw(p, o + 1);
        let natoms: i32 = pw(p, o + 2);
        let nul: i32 = pw(p, o + 3);
        let fo: i32 = o + 4;
        let fl: i32 = fo + (2 * w);
        let r#as: i32 = fl + (npos * w);
        let am: i32 = r#as + natoms;
        if !spend(s, npos + natoms) {
            return false;
        }
        if (nul < 0) || (nul > 1) {
            return want(s, false, o, C_REGEXP);
        }
        if (!row_clean(p, fo, w, npos)) || (!row_clean(p, fo + w, w, npos)) {
            return want(s, false, fo, C_REGEXP);
        }
        for q in 0..npos {
            if !row_clean(p, fl + (q * w), w, npos) {
                return want(s, false, fl + (q * w), C_REGEXP);
            }
        }
        if pw(p, r#as) != 0 {
            return want(s, false, r#as, C_REGEXP);
        }
        for i in 0..natoms {
            let st: i32 = pw(p, r#as + i);
            if (st < 0) || (st > 1114111) {
                return want(s, false, r#as + i, C_REGEXP);
            }
            if (i > 0) && (st <= pw(p, r#as + (i - 1))) {
                return want(s, false, r#as + i, C_REGEXP);
            }
            if !row_clean(p, am + (i * w), w, npos) {
                return want(s, false, am + (i * w), C_REGEXP);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn ts_within(p: &[i32], s: &mut [i32], t: i32, e: i32) -> bool {
    // Is every leaf of t's evaluation list marked e?
    let n: i32 = ts_eval_n(p, t);
    for i in 0..n {
        let l: i32 = ts_eval_at(p, t, i);
        if (!in_range(l, pw(p, W_N_LEAVES))) || (mark_get(s, l) != e) {
            return false;
        }
    }
    return true;
}
pub(crate) fn child_ts(p: &[i32], l: i32, i: i32) -> i32 {
    // Child typeset i of leaf l (program.md §4.2's Children column), or -2 past
    // the last.
    let o: i32 = leaf_at(p, l);
    let k: i32 = pw(p, o) & 255;
    let d0: i32 = pw(p, o + 2);
    if (k == 1) || ((k == 2) && ((d0 >= 4) && (d0 <= 6))) {
        if i == 0 {
            return pw(p, W_TS_ANY);
        }
        return -2;
    }
    if k == 11 {
        if i == 0 {
            return pw(p, o + 4);
        }
        return -2;
    }
    if k == 12 {
        if i == 0 {
            return pw(p, o + 6);
        }
        return -2;
    }
    if k == 13 {
        if i == 0 {
            return d0;
        }
        return -2;
    }
    if k == 14 {
        let ao: i32 = rec(p, 9, d0);
        let npos: i32 = pw(p, ao);
        let w: i32 = pw(p, ao + 1);
        if i >= npos {
            return -2;
        }
        return pw(p, ((ao + 4) + w) + i);
    }
    // maps (kind 15): see map-children-within / map-has-children
    return -2;
}
pub(crate) fn map_children_within(p: &[i32], s: &mut [i32], l: i32, e: i32) -> bool {
    // Every member's key typeset (non-literal keys) and value typeset, and
    // key_ts, marked e (program-2 §7's closure children).
    let mo: i32 = rec(p, 7, pw(p, leaf_at(p, l) + 2));
    let nm: i32 = pw(p, mo + 1);
    let kts: i32 = pw(p, mo + 3);
    let nt: i32 = pw(p, W_N_TYPESETS);
    for i in 0..nm {
        let e2: i32 = (mo + 8) + (5 * i);
        let kt: i32 = pw(p, e2 + 1);
        let vt: i32 = pw(p, e2 + 2);
        if !spend(s, 2) {
            return false;
        }
        if kt >= 0 {
            if (!in_range(kt, nt)) || (!ts_within(p, s, kt, e)) {
                return false;
            }
        }
        if (!in_range(vt, nt)) || (!ts_within(p, s, vt, e)) {
            return false;
        }
    }
    if kts >= 0 {
        if (!in_range(kts, nt)) || (!ts_within(p, s, kts, e)) {
            return false;
        }
    }
    return true;
}
pub(crate) fn map_has_children(p: &[i32], l: i32) -> bool {
    let mo: i32 = rec(p, 7, pw(p, leaf_at(p, l) + 2));
    let nm: i32 = pw(p, mo + 1);
    let nt: i32 = pw(p, W_N_TYPESETS);
    for i in 0..nm {
        let e2: i32 = (mo + 8) + (5 * i);
        let kt: i32 = pw(p, e2 + 1);
        let vt: i32 = pw(p, e2 + 2);
        if in_range(kt, nt) && (ts_eval_n(p, kt) > 0) {
            return true;
        }
        if in_range(vt, nt) && (ts_eval_n(p, vt) > 0) {
            return true;
        }
    }
    return false;
}
pub(crate) fn children_within(p: &[i32], s: &mut [i32], cs: i32, e: i32) -> bool {
    // Is every child (closed) of every leaf of cset cs marked e?
    let co: i32 = rec(p, 16, cs);
    let n: i32 = pw(p, co);
    for i in 0..n {
        let l: i32 = pw(p, co + (3 + i));
        let mut j: i32 = 0;
        if leaf_kind(p, l) == 15 {
            if !map_children_within(p, s, l, e) {
                return false;
            }
        }
        loop {
            if !spend(s, 1) {
                return false;
            }
            let t: i32 = child_ts(p, l, j);
            if t == (-2) {
                break;
            }
            if !in_range(t, pw(p, W_N_TYPESETS)) {
                return false;
            }
            if !ts_within(p, s, t, e) {
                return false;
            }
            j += 1;
        }
    }
    return true;
}
pub(crate) fn has_children(p: &[i32], cs: i32) -> bool {
    let co: i32 = rec(p, 16, cs);
    let n: i32 = pw(p, co);
    for i in 0..n {
        let l: i32 = pw(p, co + (3 + i));
        if (leaf_kind(p, l) == 15) && map_has_children(p, l) {
            return true;
        }
        if child_ts(p, l, 0) != (-2) {
            let t0: i32 = child_ts(p, l, 0);
            // a child typeset that is empty is no child at all
            if in_range(t0, pw(p, W_N_TYPESETS)) && (ts_eval_n(p, t0) > 0) {
                return true;
            }
            let mut j: i32 = 1;
            loop {
                let t: i32 = child_ts(p, l, j);
                if t == (-2) {
                    break;
                }
                if in_range(t, pw(p, W_N_TYPESETS)) && (ts_eval_n(p, t) > 0) {
                    return true;
                }
                j += 1;
            }
        }
    }
    return false;
}
pub(crate) fn cset_frame(p: &[i32], co: i32, n: i32) -> i32 {
    // frame_words of the cset at co (program-2 §9.2): 2n + max(MAPAREA, ARRAREA),
    // MAPAREA = the maps' block words + 4 cand_max (n_members + the largest
    // naming count), ARRAREA = the arrays' block words.
    let mut maparea: i32 = 0;
    let mut candmax: i32 = 0;
    let mut arrarea: i32 = 0;
    for i in 0..n {
        let l: i32 = pw(p, co + (3 + i));
        let o: i32 = leaf_at(p, l);
        let k: i32 = pw(p, o) & 255;
        if k == 15 {
            let mo: i32 = rec(p, 7, pw(p, o + 2));
            let cand: i32 = pw(p, mo + 1) + map_namers_max(p, mo);
            maparea += leaf_block(p, l);
            if cand > candmax {
                candmax = cand;
            }
        }
        if k == 14 {
            arrarea += leaf_block(p, l);
        }
    }
    maparea += 4 * candmax;
    if arrarea > maparea {
        maparea = arrarea;
    }
    return (2 * n) + maparea;
}
pub(crate) fn cset_regex(p: &[i32], co: i32, n: i32) -> i32 {
    let mut w: i32 = 0;
    for i in 0..n {
        let l: i32 = pw(p, co + (3 + i));
        let o: i32 = leaf_at(p, l);
        if ((pw(p, o) & 255) == 8) && (pw(p, o + 4) >= 0) {
            let ro: i32 = rec(p, 11, pw(p, o + 4));
            w += 2 * pw(p, ro + 1);
        }
    }
    return w;
}
pub(crate) fn check_csets(p: &[i32], s: &mut [i32]) -> bool {
    let nc: i32 = pw(p, W_N_CSETS);
    let nl: i32 = pw(p, W_N_LEAVES);
    for c in 0..nc {
        let co: i32 = rec(p, 16, c);
        let n: i32 = pw(p, co);
        let e: i32 = epoch(s);
        if !spend(s, 1 + n) {
            return false;
        }
        for i in 0..n {
            let l: i32 = pw(p, co + (3 + i));
            if !in_range(l, nl) {
                return want(s, false, co + (3 + i), C_CSET);
            }
            if (i > 0) && (l <= pw(p, co + (2 + i))) {
                return want(s, false, co + (3 + i), C_CSET);
            }
            mark_set(s, l, e);
        }
        // closed under combinator operands
        for j in 0..n {
            let l2: i32 = pw(p, co + (3 + j));
            if combinator(p, l2) {
                let lo: i32 = leaf_at(p, l2);
                if (mark_get(s, pw(p, lo + 2)) != e) || (mark_get(s, pw(p, lo + 3)) != e) {
                    return want(s, false, co + (3 + j), C_CSET);
                }
            }
        }
        if pw(p, co + 1) != cset_frame(p, co, n) {
            return want(s, false, co + 1, C_DERIVED);
        }
        if pw(p, co + 2) != cset_regex(p, co, n) {
            return want(s, false, co + 2, C_DERIVED);
        }
    }
    return !failed(s);
}
pub(crate) fn check_arena_words(p: &[i32], s: &mut [i32]) -> bool {
    // Header words 29 R_ITEM_MAX, 62 RECLEAF_MAX and 63 ACT_SUM [D]: over closure
    // sets, the largest sum of A2 / T record words, count of recursive
    // ARRAY / MAP leaves and sum of their activation words (program-2 §2, §5.3).
    let nc: i32 = pw(p, W_N_CSETS);
    let mut ritem: i32 = 0;
    let mut reclmax: i32 = 0;
    let mut actsum: i32 = 0;
    for c in 0..nc {
        let co: i32 = rec(p, 16, c);
        let n: i32 = pw(p, co);
        let mut rs: i32 = 0;
        let mut rc: i32 = 0;
        let mut asum: i32 = 0;
        if !spend(s, 1 + n) {
            return false;
        }
        for i in 0..n {
            let l: i32 = pw(p, co + (3 + i));
            let k: i32 = leaf_kind(p, l);
            if (k == 14) || (k == 15) {
                let po: i32 = leaf_peg(p, l);
                let calls: i32 = pw(p, po + 8);
                rs = sadd(rs, leaf_recwords(p, l));
                if calls > 0 {
                    rc += 1;
                    asum = sadd(asum, act_words(calls, pw(p, po + 6)));
                }
            }
        }
        if rs > ritem {
            ritem = rs;
        }
        if rc > reclmax {
            reclmax = rc;
        }
        if asum > actsum {
            actsum = asum;
        }
    }
    if pw(p, W_R_ITEM_MAX) != ritem {
        return want(s, false, W_R_ITEM_MAX, C_DERIVED);
    }
    if pw(p, W_RECLEAF_MAX) != reclmax {
        return want(s, false, W_RECLEAF_MAX, C_DERIVED);
    }
    if pw(p, W_ACT_SUM) != actsum {
        return want(s, false, W_ACT_SUM, C_DERIVED);
    }
    return true;
}
pub(crate) fn check_chains(p: &[i32], s: &mut [i32]) -> bool {
    let nch: i32 = pw(p, W_N_CHAINS);
    let ncs: i32 = pw(p, W_N_CSETS);
    let d: i32 = pw(p, 32);
    for c in 0..nch {
        let o: i32 = rec(p, 18, c);
        let n: i32 = pw(p, o);
        let r: i32 = pw(p, o + 1);
        if n > (d + 1) {
            return want(s, false, o, C_CHAIN);
        }
        if (r < (-1)) || (r >= n) {
            return want(s, false, o, C_CHAIN);
        }
        for i in 0..n {
            if !in_range(pw(p, o + (2 + i)), ncs) {
                return want(s, false, o + (2 + i), C_CHAIN);
            }
        }
        // cset[k+1] holds the children of cset[k]; the period closes; an
        // ending chain ends with no children
        for k in 0..n - 1 {
            let e: i32 = epoch(s);
            let nxt: i32 = pw(p, o + (3 + k));
            let no: i32 = rec(p, 16, nxt);
            for q in 0..pw(p, no) {
                mark_set(s, pw(p, no + (3 + q)), e);
            }
            if !children_within(p, s, pw(p, o + (2 + k)), e) {
                return want(s, false, o + (2 + k), C_CHAIN);
            }
        }
        if r >= 0 {
            let e2: i32 = epoch(s);
            let rc: i32 = pw(p, o + (2 + r));
            let ro: i32 = rec(p, 16, rc);
            for q2 in 0..pw(p, ro) {
                mark_set(s, pw(p, ro + (3 + q2)), e2);
            }
            if !children_within(p, s, pw(p, o + (2 + (n - 1))), e2) {
                return want(s, false, o, C_CHAIN);
            }
        } else if n <= d {
            if has_children(p, pw(p, o + (2 + (n - 1)))) {
                return want(s, false, o, C_CHAIN);
            }
        }
    }
    return !failed(s);
}
pub(crate) fn rule_scratch(p: &[i32], chain: i32) -> i32 {
    // program.md §12.1's scratch words for a rule with this chain (MARK_CAP =
    // N_LEAVES).
    let o: i32 = rec(p, 18, chain);
    let n: i32 = pw(p, o);
    let r: i32 = pw(p, o + 1);
    let d: i32 = pw(p, 32);
    let nl: i32 = pw(p, W_N_LEAVES);
    let mut sumf: i32 = 0;
    let mut maxr: i32 = 0;
    for k in 0..d + 1 {
        let mut idx: i32 = k;
        if k >= n {
            if r < 0 {
                idx = -1;
            } else {
                idx = r + ((k - r) - (((k - r) / (n - r)) * (n - r)));
            }
        }
        if idx >= 0 {
            let co: i32 = rec(p, 16, pw(p, o + (2 + idx)));
            sumf += pw(p, co + 1);
            if pw(p, co + 2) > maxr {
                maxr = pw(p, co + 2);
            }
        }
    }
    return ((48 + (2 * nl)) + (2 * (d + 1))) + (maxr + sumf);
}
pub(crate) fn check_rule_closure(p: &[i32], s: &mut [i32]) -> bool {
    // R_0 holds the rule's evaluation list; scratch_words; SCRATCH_MAX; flags;
    // the total-bytes cap.
    let base: i32 = sec(p, 0);
    let nr: i32 = pw(p, W_N_RULES);
    let mut smax: i32 = 0;
    for i in 0..nr {
        let o: i32 = base + (5 * i);
        let t: i32 = pw(p, o + 2);
        let ch: i32 = pw(p, o + 3);
        let co: i32 = rec(p, 18, ch);
        let c0: i32 = pw(p, co + 2);
        let c0o: i32 = rec(p, 16, c0);
        let e: i32 = epoch(s);
        if !spend(s, pw(p, c0o)) {
            return false;
        }
        for q in 0..pw(p, c0o) {
            mark_set(s, pw(p, c0o + (3 + q)), e);
        }
        if !ts_within(p, s, t, e) {
            return want(s, false, o, C_CHAIN);
        }
        let sw: i32 = rule_scratch(p, ch);
        if pw(p, o + 4) != sw {
            return want(s, false, o + 4, C_DERIVED);
        }
        if sw > smax {
            smax = sw;
        }
    }
    if pw(p, 40) != smax {
        return want(s, false, 40, C_DERIVED);
    }
    let total: i32 = pw(p, 38);
    let words: i32 = p.len() as i32;
    let pool: i32 = pw(p, 4);
    if (smax > (total / 4)) || (words > (((total - pool) - (4 * smax)) / 4)) {
        return want(s, false, 38, C_TOTAL);
    }
    return !failed(s);
}
pub(crate) fn check_flags(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    let mut f: i32 = 0;
    let mut needs_any: bool = false;
    for kq in 0..pw(p, W_N_KEYS) {
        let ko: i32 = pw(p, sec(p, 4) + (2 * kq));
        if (i32::cast_unsigned(b[(ko) as usize] as i32) >> 5).cast_signed() <= 1 {
            f |= 1;
        }
    }
    for l in 0..pw(p, W_N_LEAVES) {
        let o: i32 = leaf_at(p, l);
        let k: i32 = pw(p, o) & 255;
        if (k == 8) && (pw(p, o + 4) >= 0) {
            f |= 2;
        }
        if k == 13 {
            f |= 4;
        }
        if (k == 16) || (k == 17) {
            f |= 8;
        }
        if k == 18 {
            f |= 16;
        }
        if (k == 14) && (pw(p, leaf_peg(p, l) + 3) == TIER_A2) {
            f |= 64;
        }
        if (k == 15) && (pw(p, leaf_peg(p, l) + 3) == TIER_T) {
            f |= 64;
        }
        if (k == 1) || ((k == 2) && ((pw(p, o + 2) >= 4) && (pw(p, o + 2) <= 6))) {
            needs_any = true;
        }
    }
    // bit 5 (CUTS_BRANCH, D301) is the compile option [V]; bit 6 (ARENA) is derived
    if (pw(p, 6) & (!32)) != f {
        return want(s, false, 6, C_DERIVED);
    }
    if needs_any && (pw(p, W_TS_ANY) < 0) {
        return want(s, false, W_TS_ANY, C_HEADER);
    }
    return true;
}
pub(crate) fn name_byte_ok(c: i32, first: bool) -> bool {
    // A control name: ASCII letters and `_`, then also digits and `-`.
    if ((c >= 65) && (c <= 90)) || (((c >= 97) && (c <= 122)) || (c == 95)) {
        return true;
    }
    if first {
        return false;
    }
    return ((c >= 48) && (c <= 57)) || (c == 45);
}
pub(crate) fn check_exts(p: &[i32], b: &[u8], s: &mut [i32]) -> bool {
    // The names of the N_EXTS extension controls: deterministic CBOR text
    // strings of 1..64 name bytes, strictly ascending bytewise, back to back
    // filling pool[W_EXT_NAMES, + W_EXT_NAMES_LEN) exactly; none without any.
    let n: i32 = pw(p, W_N_EXTS);
    let off: i32 = pw(p, W_EXT_NAMES);
    let len: i32 = pw(p, W_EXT_NAMES_LEN);
    if n == 0 {
        return want(s, (off == 0) && (len == 0), W_EXT_NAMES, C_EXT);
    }
    if !want(s, byte_range(b, off, len), W_EXT_NAMES, C_EXT) {
        return false;
    }
    if !spend(s, n + (len / 4)) {
        return false;
    }
    let end: i32 = off + len;
    let mut i: i32 = off;
    let mut po: i32 = -1;
    let mut pl: i32 = 0;
    for _k in 0..n {
        if i >= end {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        let ib: i32 = b[(i) as usize] as i32;
        let mut nl: i32 = ib & 31;
        let mut c: i32 = i + 1;
        if (i32::cast_unsigned(ib) >> 5).cast_signed() != 3 {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        if nl > 24 {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        if nl == 24 {
            if c >= end {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
            nl = b[(c) as usize] as i32;
            if nl < 24 {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
            c += 1;
        }
        if (nl < 1) || ((nl > 64) || (nl > (end - c))) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        for j in 0..nl {
            if !name_byte_ok(b[(c + j) as usize] as i32, j == 0) {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
        }
        if (po >= 0) && (bytes_cmp(b, po, pl, c, nl) >= 0) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        po = c;
        pl = nl;
        i = c + nl;
    }
    return want(s, i == end, W_EXT_NAMES, C_EXT);
}
pub fn vm_verify(p: &[i32], b: &[u8], s: &mut [i32]) -> i32 {
    // 0 valid; -1 refused (detail in S[35], S[36]); -2 the scratch is too small
    // for the verifier's marks and PEG working area (len(S) >= vm-verify-words,
    // VM_MARK_CAP >= N_LEAVES).
    if (s.len() as i32) < 48 {
        return -2;
    }
    s[(V_FAILED) as usize] = 0;
    s[(VM_DETAIL) as usize] = 0;
    s[(VM_DETAIL + 1) as usize] = 0;
    if !check_header(p, b, s) {
        return -1;
    }
    let m: i32 = s[(VM_MARK_CAP) as usize];
    let nl: i32 = p[(W_N_LEAVES) as usize];
    if (m < nl) || ((m < 0) || ((48 + (2 * m)) > (s.len() as i32))) {
        return -2;
    }
    if ((48 + (2 * m)) + vm_verify_temp(p)) > (s.len() as i32) {
        return -2;
    }
    // the verify budget: 64 * (PROGRAM_WORDS + POOL_BYTES / 4 + 1)
    let units: i32 = ((p.len() as i32) + ((b.len() as i32) / 4)) + 1;
    if units > (INF / 64) {
        s[(V_BUDGET) as usize] = INF;
    } else {
        s[(V_BUDGET) as usize] = 64 * units;
    }
    if !check_index(p, s, 2, 3, pw(p, W_N_TYPESETS), 0) {
        return -1;
    }
    if !check_index(p, s, 5, 6, pw(p, W_N_PEGS), 1) {
        return -1;
    }
    if !check_index(p, s, 7, 8, pw(p, W_N_MAPS), 2) {
        return -1;
    }
    if !check_index(p, s, 9, 10, pw(p, W_N_ARRAYS), 3) {
        return -1;
    }
    if !check_index(p, s, 11, 12, pw(p, W_N_REGEXPS), 4) {
        return -1;
    }
    if !check_index(p, s, 16, 17, pw(p, W_N_CSETS), 5) {
        return -1;
    }
    if !check_index(p, s, 18, 19, pw(p, W_N_CHAINS), 6) {
        return -1;
    }
    if !check_exts(p, b, s) {
        return -1;
    }
    if !check_iv_records(p, b, s) {
        return -1;
    }
    if !check_leaves(p, b, s) {
        return -1;
    }
    if !check_typesets(p, s) {
        return -1;
    }
    if !check_keys(p, b, s) {
        return -1;
    }
    if !check_rules(p, b, s) {
        return -1;
    }
    if !check_pegs(p, s) {
        return -1;
    }
    if !check_maps(p, s) {
        return -1;
    }
    if !check_arrays(p, s) {
        return -1;
    }
    if !check_regexps(p, s) {
        return -1;
    }
    if !check_flags(p, b, s) {
        return -1;
    }
    if !check_csets(p, s) {
        return -1;
    }
    if !check_chains(p, s) {
        return -1;
    }
    if !check_rule_closure(p, s) {
        return -1;
    }
    if !check_arena_words(p, s) {
        return -1;
    }
    if failed(s) {
        return -1;
    }
    return 0;
}
pub fn vm_verify_temp(p: &[i32]) -> i32 {
    // Words of PEG working area vm-verify needs after the marks: the largest
    // 7 n + 2 W (n + 1) + npos W over the programs (n <= 16384) and arrays
    // (npos <= 4096, so W <= 128), read defensively (checked reads, clamped), so
    // an unverified Program can ask for at most the hard maxima's worth.
    if (p.len() as i32) < 64 {
        return 0;
    }
    let lim: i32 = p.len() as i32;
    let mut nmax: i32 = 1;
    let mut npmax: i32 = 0;
    let mut np: i32 = pw(p, W_N_PEGS);
    let mut na: i32 = pw(p, W_N_ARRAYS);
    if (np < 0) || (np > lim) {
        np = 0;
    }
    if (na < 0) || (na > lim) {
        na = 0;
    }
    for g in 0..np {
        let n: i32 = pw(p, i32::wrapping_add(pw(p, i32::wrapping_add(pw(p, W_SEC + 5), g)), 1));
        if (n > nmax) && (n <= 16384) {
            nmax = n;
        }
    }
    for a in 0..na {
        let npos: i32 = pw(p, pw(p, i32::wrapping_add(pw(p, W_SEC + 9), a)));
        if (npos > npmax) && (npos <= 4096) {
            npmax = npos;
        }
    }
    let w: i32 = (npmax + 31) >> 5;
    return ((7 * nmax) + ((2 * w) * (nmax + 1))) + ((npmax * w) + 16);
}
pub fn vm_verify_words(p: &[i32], mark_cap: i32) -> i32 {
    // The scratch length vm-verify needs with VM_MARK_CAP = max(mark-cap,
    // N_LEAVES clamped to 2^20): 48 + 2 M + the PEG working area.
    let mut m: i32 = mark_cap;
    let mut nl: i32 = 0;
    if (p.len() as i32) >= 64 {
        nl = pw(p, W_N_LEAVES);
    }
    if (nl < 0) || (nl > 1048576) {
        nl = 1048576;
    }
    if nl > m {
        m = nl;
    }
    if m < 1 {
        m = 1;
    }
    return (48 + (2 * m)) + vm_verify_temp(p);
}
